"use client";

import type { ComponentProps } from "react";
import { cn } from "@repo/design-system/lib/utils";
import { MetricCard } from "./primitives/metric-card";

type InteractiveMetricCardProps = {
  active?: boolean;
  onClick?: () => void;
} & ComponentProps<typeof MetricCard>;

export function InteractiveMetricCard({
  active = false,
  className,
  onClick,
  ...props
}: Readonly<InteractiveMetricCardProps>) {
  const card = (
    <MetricCard
      className={cn(
        active
          ? "border-emerald-500/70 bg-emerald-900/30 ring-1 ring-emerald-500/30 [&_[data-slot=card-description]]:text-emerald-200/80 [&_[data-slot=card-title]]:text-emerald-400"
          : "border-slate-700/50 bg-slate-800/60 hover:border-slate-600 [&_[data-slot=card-description]]:text-slate-400 [&_[data-slot=card-title]]:text-white",
        className
      )}
      {...props}
    />
  );

  if (!onClick) {
    return card;
  }

  return (
    <button
      aria-pressed={active}
      className="w-full rounded-xl text-left"
      onClick={onClick}
      type="button"
    >
      {card}
    </button>
  );
}
